<script>
  // Tab count animation
  const countEl = document.getElementById('tabCount')!;
  let current = 847;

  function incrementCount() {
    current += Math.floor(Math.random() * 3) + 1;
    countEl.textContent = current.toLocaleString();
  }
  setInterval(incrementCount, 3000);

  // Purge tabs animation
  const tabs = document.querySelectorAll('.doomed-tab');
  const flash = document.getElementById('purgeFlash')!;

  function purgeTabs() {
    tabs.forEach((tab, i) => {
      setTimeout(() => {
        tab.classList.add('purged');
      }, i * 120);
    });

    flash.classList.add('active');
    setTimeout(() => flash.classList.remove('active'), 800);

    setTimeout(() => {
      tabs.forEach(tab => tab.classList.remove('purged'));
    }, 3500);
  }

  setTimeout(() => {
    purgeTabs();
    setInterval(purgeTabs, 5000);
  }, 2000);
</script>

