        src: url('/fonts/Monocraft-Bold.woff2') format('woff2');
        font-weight: 700;
        font-display: swap;
      }

      :root {
        --bg: #080808;
        --bg-card: #111111;
        --bg-card-hover: #1a1a1a;
        --text: #e8e4df;
        --text-dim: #8a8580;
        --text-bright: #faf7f2;
        --fire: #ff4500;
        --fire-bright: #ff6b35;
        --fire-deep: #c41e00;
        --ember: #ff8c42;
        --ash: #2a2420;
        --mono: 'Monocraft', monospace;
        --sans: 'DM Sans', system-ui, sans-serif;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        font-family: var(--sans);
        background: var(--bg);
        color: var(--text);
        line-height: 1.6;
        overflow-x: hidden;
        -webkit-font-smoothing: antialiased;
      }

      a {
        color: inherit;
        text-decoration: none;
      }

      /* ===== SECTIONS ===== */
      .section-inner {
        max-width: 1100px;
        margin: 0 auto;
        padding: 7rem 2rem;
      }

      section h2 {
        font-family: var(--mono);
        font-size: clamp(2.2rem, 5vw, 3.8rem);
        font-weight: 400;
        line-height: 1.15;
        letter-spacing: 0.02em;
        color: var(--text-bright);
        margin-bottom: 1rem;
      }

      section h2 em {
        color: var(--fire);
      }

      .section-sub {
        font-size: 1.1rem;
        color: var(--text-dim);
        max-width: 560px;
        line-height: 1.7;
      }

      /* ===== BUTTONS ===== */
      .btn {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        font-family: var(--sans);
        font-size: 0.95rem;
        font-weight: 500;
        padding: 0.85rem 1.8rem;
        border-radius: 8px;
        cursor: pointer;
        transition: all 0.25s;
        position: relative;
        overflow: hidden;
        letter-spacing: 0.01em;
      }

      .btn-primary {
        background: var(--fire);
        color: #fff;
        border: none;
        box-shadow: 0 0 30px rgba(255, 69, 0, 0.15);
      }

      .btn-primary:hover {
        background: var(--fire-bright);
        transform: translateY(-2px);
        box-shadow: 0 8px 30px rgba(255, 69, 0, 0.35);
      }

      .btn-flame {
        position: absolute;
        inset: 0;
        background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.1), transparent);
        transform: translateX(-100%);
        transition: transform 0.5s;
      }

      .btn-primary:hover .btn-flame {
        transform: translateX(100%);
      }

      .btn-ghost {
        background: transparent;
        color: var(--text-dim);
        border: 1px solid rgba(255, 255, 255, 0.08);
      }

      .btn-ghost:hover {
        color: var(--text);
        border-color: rgba(255, 255, 255, 0.15);
        background: rgba(255, 255, 255, 0.03);
      }

      .btn-lg {
        font-size: 1.1rem;
        padding: 1.1rem 2.4rem;
        border-radius: 10px;
      }

      /* ===== ANIMATIONS ===== */
      @keyframes fadeInUp {
        from {
          opacity: 0;
          transform: translateY(24px);
        }
        to {
          opacity: 1;
          transform: translateY(0);
        }
      }

      @keyframes fadeInDown {
        from {
          opacity: 0;
          transform: translateY(-16px);
        }
        to {
          opacity: 1;
          transform: translateY(0);
        }
      }

      @keyframes tabSlideIn {
        from {
          opacity: 0;
          transform: translateX(-20px);
        }
        to {
          opacity: 1;
          transform: translateX(0);
        }
      }

      @keyframes tabPurge {
        0% {
          opacity: 1;
          transform: translateX(0) scale(1);
          filter: brightness(1);
        }
        30% {
          filter: brightness(2);
          background: rgba(255, 69, 0, 0.15);
        }
        100% {
          opacity: 0;
          transform: translateX(100px) scale(0.8);
          filter: brightness(0.5);
        }
      }

      @keyframes pulse {
        0%, 100% { opacity: 0.5; transform: translate(-50%, -50%) scale(1); }
        50% { opacity: 1; transform: translate(-50%, -50%) scale(1.1); }
      }

      /* ===== SCROLL REVEAL ===== */
      .reveal {
        opacity: 0;
        transform: translateY(30px);
        transition: opacity 0.7s ease-out, transform 0.7s ease-out;
      }

      .reveal.visible {
        opacity: 1;
        transform: translateY(0);
      }

      /* ===== RESPONSIVE ===== */
      @media (max-width: 768px) {
        .section-inner {
          padding: 5rem 1.5rem;
        }
      }
    </style>

    <style>
      /* ===== EMBER CANVAS ===== */
      #embers {
        position: fixed;
        inset: 0;
        z-index: 0;
        pointer-events: none;
        opacity: 0.6;
      }

      /* ===== NAV ===== */
      nav {
        position: fixed;
        top: 0;
        left: 0;
        right: 0;
        z-index: 100;
        padding: 1rem 2rem;
        background: rgba(8, 8, 8, 0.85);
        backdrop-filter: blur(16px);
        border-bottom: 1px solid rgba(255, 69, 0, 0.08);
      }

      .nav-inner {
        max-width: 1200px;
        margin: 0 auto;
        display: flex;
        align-items: center;
        justify-content: space-between;
      }

      .logo {
        display: flex;
        align-items: center;
        gap: 0.6rem;
        font-family: var(--mono);
        font-size: 1.3rem;
        letter-spacing: 0.02em;
        color: var(--text-bright);
      }

      .logo-icon {
        font-size: 1.6rem;
        filter: drop-shadow(0 0 8px rgba(255, 69, 0, 0.5));
      }

      .logo-icon.small {
        font-size: 1.2rem;
      }

      .nav-cta {
        font-size: 0.85rem;
        font-weight: 500;
        padding: 0.55rem 1.2rem;
        border-radius: 6px;
        background: var(--fire);
        color: #fff;
        transition: all 0.2s;
        letter-spacing: 0.01em;
      }

      .nav-cta:hover {
        background: var(--fire-bright);
        transform: translateY(-1px);
        box-shadow: 0 4px 20px rgba(255, 69, 0, 0.3);
      }

      /* ===== FOOTER ===== */
      footer {
        position: relative;
        z-index: 1;
        border-top: 1px solid rgba(255, 255, 255, 0.04);
        padding: 2rem;
      }

      .footer-inner {
        max-width: 1100px;
        margin: 0 auto;
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 0.75rem;
        font-size: 0.8rem;
        color: var(--text-dim);
      }

      .footer-inner a {
        color: var(--text-dim);
        transition: color 0.2s;
      }

      .footer-inner a:hover {
        color: var(--fire);
      }

      .sep {
        opacity: 0.3;
      }

      @media (max-width: 480px) {
        .nav-cta {
          font-size: 0.75rem;
          padding: 0.45rem 0.9rem;
        }
      }
    </style>

    <script>
      // ===== EMBER PARTICLES =====
      const canvas = document.getElementById('embers') as HTMLCanvasElement;
      const ctx = canvas.getContext('2d')!;
      let particles: Ember[] = [];

      function resize() {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
      }
      resize();
      window.addEventListener('resize', resize);

      class Ember {
        x: number;
        y: number;
        size: number;
        speedX: number;
        speedY: number;
        life: number;
        maxLife: number;
        opacity: number;

        constructor() {
          this.x = Math.random() * canvas.width;
          this.y = canvas.height + 10;
          this.size = Math.random() * 2.5 + 0.5;
          this.speedX = (Math.random() - 0.5) * 0.8;
          this.speedY = -(Math.random() * 1.2 + 0.3);
          this.maxLife = Math.random() * 300 + 200;
          this.life = 0;
          this.opacity = 0;
        }

        update() {
          this.x += this.speedX + Math.sin(this.life * 0.02) * 0.3;
          this.y += this.speedY;
          this.life++;
          this.opacity = Math.sin((this.life / this.maxLife) * Math.PI) * 0.7;
          return this.life < this.maxLife;
        }

        draw() {
          const gradient = ctx.createRadialGradient(this.x, this.y, 0, this.x, this.y, this.size * 2);
          gradient.addColorStop(0, `rgba(255, 140, 66, ${this.opacity})`);
          gradient.addColorStop(0.5, `rgba(255, 69, 0, ${this.opacity * 0.5})`);
          gradient.addColorStop(1, `rgba(196, 30, 0, 0)`);
          ctx.beginPath();
          ctx.arc(this.x, this.y, this.size * 2, 0, Math.PI * 2);
          ctx.fillStyle = gradient;
          ctx.fill();
        }
      }

      function animateEmbers() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        if (Math.random() < 0.15) {
          particles.push(new Ember());
        }
        particles = particles.filter(p => {
          const alive = p.update();
          if (alive) p.draw();
          return alive;
        });
        requestAnimationFrame(animateEmbers);
      }
      animateEmbers();

      // ===== STATS COUNTER =====
      function animateStats() {
        const stats = document.querySelectorAll('.stat-num');
        stats.forEach(el => {
          const target = parseInt(el.getAttribute('data-target') || '0');
          const duration = 2000;
          const start = performance.now();

          function tick(now: number) {
            const elapsed = now - start;
            const progress = Math.min(elapsed / duration, 1);
            const eased = 1 - Math.pow(1 - progress, 3);
            const value = Math.floor(target * eased);
            el.textContent = value.toLocaleString();
            if (progress < 1) requestAnimationFrame(tick);
          }
          requestAnimationFrame(tick);
        });
      }

      // ===== SCROLL REVEAL =====
      const revealElements = document.querySelectorAll(
        '.pain-card, .feature-card, .step, .quote-card, .stat'
      );

      revealElements.forEach(el => el.classList.add('reveal'));

      let statsAnimated = false;
      const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('visible');
            observer.unobserve(entry.target);
          }
        });

        if (!statsAnimated) {
          const statsBar = document.querySelector('.stats-bar');
          if (statsBar) {
            const rect = statsBar.getBoundingClientRect();
            if (rect.top < window.innerHeight * 0.8) {
              statsAnimated = true;
              animateStats();
            }
          }
        }
      }, { threshold: 0.15 });

      revealElements.forEach(el => observer.observe(el));
    </script>
  </body>
</html>

